// Machine à états de l'onboarding (WF6).
//
// Fonction pure : (enveloppe WF1, référentiels API) -> (état suivant, brouillon,
// appel Telegram à émettre). Aucun effet de bord ici — les nœuds qui suivent
// écrivent en base, appellent l'API et envoient le message.
//
// États : IDLE -> ASK_LANGUAGE -> ASK_NAME -> ASK_WEIGHT -> ASK_DISEASES
//         -> ASK_ALLERGENS -> DONE

const enveloppe = $('Execute Workflow Trigger').first().json;
const maladies = $('Référentiel maladies').all().map((i) => i.json);
const allergenes = $('Référentiel allergènes').all().map((i) => i.json);

// ---------------------------------------------------------------- utilitaires

function echapper(v) {
  return String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function clavierLangue() {
  return {
    inline_keyboard: [
      [
        { text: '🇸🇳 Wolof', callback_data: 'onb_lang_wo' },
        { text: '🇫🇷 Français', callback_data: 'onb_lang_fr' },
        { text: '🇬🇧 English', callback_data: 'onb_lang_en' },
      ],
    ],
  };
}

// Clavier à cases à cocher : 2 colonnes, puis « aucune » et « valider ».
function clavierSelection(items, selection, prefixe, libelleAucune, libelleValider) {
  const lignes = [];
  for (let i = 0; i < items.length; i += 2) {
    lignes.push(
      items.slice(i, i + 2).map((item) => ({
        text: (selection.includes(item.id) ? '☑️ ' : '▫️ ') + item.name,
        callback_data: `${prefixe}_${item.id}`,
      })),
    );
  }
  lignes.push([{ text: libelleAucune, callback_data: `${prefixe}_none` }]);
  lignes.push([{ text: libelleValider, callback_data: `${prefixe}_ok` }]);
  return { inline_keyboard: lignes };
}

function bascule(selection, id) {
  return selection.includes(id) ? selection.filter((x) => x !== id) : [...selection, id];
}

function noms(liste, ids) {
  const trouves = liste.filter((x) => ids.includes(x.id)).map((x) => x.name);
  return trouves.length ? trouves.join(', ') : 'aucune';
}

// ------------------------------------------------------------------- contexte

const etat = enveloppe.session_state || 'IDLE';
const brouillon = { ...(enveloppe.session_draft || {}) };
brouillon.diseases = brouillon.diseases || [];
brouillon.allergens = brouillon.allergens || [];

const texte = (enveloppe.text || '').trim();
const bouton = enveloppe.callback_data || null;
const estBouton = enveloppe.kind === 'callback';

// Une réponse : le message Telegram à émettre. On édite le message existant
// quand l'utilisateur vient d'appuyer sur un bouton, sinon on en envoie un neuf.
function reponse(etatSuivant, corps, options = {}) {
  const editer = estBouton && enveloppe.message_id && options.editer !== false;
  return [{
    json: {
      telegram_id: enveloppe.telegram_id,
      chat_id: enveloppe.chat_id,
      callback_query_id: enveloppe.callback_query_id,
      is_callback: estBouton,
      state: etatSuivant,
      draft: brouillon,
      language: brouillon.language || enveloppe.language || 'fr',
      finalize: options.finalize === true,
      telegram_method: editer ? 'editMessageText' : 'sendMessage',
      telegram_body: {
        chat_id: enveloppe.chat_id,
        ...(editer ? { message_id: enveloppe.message_id } : {}),
        text: corps.text,
        parse_mode: 'HTML',
        ...(corps.reply_markup ? { reply_markup: corps.reply_markup } : {}),
      },
    },
  }];
}

// --------------------------------------------------------------- les questions

function demanderLangue() {
  const prenom = echapper(enveloppe.telegram_first_name || '');
  return reponse('ASK_LANGUAGE', {
    text:
      `🌟 <b>Dalal ak jamm ${prenom} !</b>\n` +
      `<b>Bienvenue sur NutriSénégal.</b>\n\n` +
      `Je vérifie si un plat convient à ta santé : allergènes, maladies chroniques, ` +
      `et des alternatives plus adaptées.\n\n` +
      `Commençons par créer ton profil.\n\n` +
      `🗣 <b>Quelle langue préfères-tu ?</b>\n` +
      `<i>Ban làkk nga gën a bëgg ? / Which language do you prefer?</i>`,
    reply_markup: clavierLangue(),
  });
}

function demanderNom(etatSuivant = 'ASK_NAME') {
  const suggestion = [enveloppe.telegram_first_name, enveloppe.telegram_last_name]
    .filter(Boolean)
    .join(' ');
  const clavier = suggestion
    ? { inline_keyboard: [[{ text: `Utiliser « ${suggestion} »`, callback_data: 'onb_name_telegram' }]] }
    : null;
  return reponse(etatSuivant, {
    text:
      `📝 <b>Comment dois-je t'appeler ?</b>\n\n` +
      `Écris ton prénom, ou prénom et nom.\n` +
      `<i>Exemple : Awa Diop</i>`,
    reply_markup: clavier,
  });
}

function demanderPoids(etatSuivant = 'ASK_WEIGHT') {
  return reponse(etatSuivant, {
    text:
      `Enchanté ${echapper(brouillon.first_name)} ! 😊\n\n` +
      `⚖️ <b>Quel est ton poids en kilos ?</b>\n` +
      `Il sert à calculer les portions et les besoins nutritionnels.\n\n` +
      `<i>Exemple : 72</i>`,
    reply_markup: { inline_keyboard: [[{ text: 'Passer cette question', callback_data: 'onb_weight_skip' }]] },
  });
}

function demanderMaladies(etatSuivant = 'ASK_DISEASES') {
  return reponse(etatSuivant, {
    text:
      `🏥 <b>As-tu une maladie chronique ?</b>\n\n` +
      `Coche tout ce qui s'applique, puis valide.\n` +
      `C'est ce qui rend l'analyse des plats pertinente.`,
    reply_markup: clavierSelection(
      maladies,
      brouillon.diseases,
      'onb_dis',
      '🚫 Aucune maladie',
      '✅ Valider',
    ),
  });
}

function demanderAllergenes(etatSuivant = 'ASK_ALLERGENS') {
  return reponse(etatSuivant, {
    text:
      `🚫 <b>As-tu des allergies alimentaires ?</b>\n\n` +
      `Coche tout ce qui s'applique, puis valide.\n` +
      `Les plats contenant ces allergènes seront écartés.`,
    reply_markup: clavierSelection(
      allergenes,
      brouillon.allergens,
      'onb_all',
      '🚫 Aucune allergie',
      '✅ Terminer',
    ),
  });
}

// ------------------------------------------------------------------ transitions

// /start relance toujours l'onboarding depuis le début
if (texte === '/start' || texte === '/restart') {
  brouillon.diseases = [];
  brouillon.allergens = [];
  return demanderLangue();
}

switch (etat) {
  case 'ASK_LANGUAGE': {
    if (bouton && bouton.startsWith('onb_lang_')) {
      brouillon.language = bouton.slice('onb_lang_'.length);
      return demanderNom();
    }
    return demanderLangue();
  }

  case 'ASK_NAME': {
    let complet = null;
    if (bouton === 'onb_name_telegram') {
      complet = [enveloppe.telegram_first_name, enveloppe.telegram_last_name].filter(Boolean).join(' ');
    } else if (texte.length >= 2) {
      complet = texte;
    }
    if (!complet) {
      return reponse('ASK_NAME', {
        text: `⚠️ Je n'ai pas compris. Écris ton prénom (2 lettres au minimum).`,
      });
    }
    const morceaux = complet.split(/\s+/);
    brouillon.first_name = morceaux[0];
    brouillon.last_name = morceaux.slice(1).join(' ');
    return demanderPoids();
  }

  case 'ASK_WEIGHT': {
    if (bouton === 'onb_weight_skip') {
      brouillon.weight = null;
      return demanderMaladies();
    }
    const poids = Number.parseFloat(texte.replace(',', '.'));
    if (!Number.isFinite(poids) || poids < 30 || poids > 300) {
      return reponse('ASK_WEIGHT', {
        text: `⚠️ Un poids entre 30 et 300 kg, en chiffres.\n<i>Exemple : 72</i>`,
      });
    }
    brouillon.weight = Math.round(poids);
    return demanderMaladies();
  }

  case 'ASK_DISEASES': {
    if (bouton === 'onb_dis_ok') return demanderAllergenes();
    if (bouton === 'onb_dis_none') {
      brouillon.diseases = [];
      return demanderMaladies();
    }
    if (bouton && bouton.startsWith('onb_dis_')) {
      brouillon.diseases = bascule(brouillon.diseases, bouton.slice('onb_dis_'.length));
      return demanderMaladies();
    }
    return demanderMaladies();
  }

  case 'ASK_ALLERGENS': {
    if (bouton === 'onb_all_ok') {
      // Le récapitulatif est écrit après les appels API, par le nœud suivant
      return reponse('DONE', { text: '⏳ Je crée ton profil…' }, { finalize: true });
    }
    if (bouton === 'onb_all_none') {
      brouillon.allergens = [];
      return demanderAllergenes();
    }
    if (bouton && bouton.startsWith('onb_all_')) {
      brouillon.allergens = bascule(brouillon.allergens, bouton.slice('onb_all_'.length));
      return demanderAllergenes();
    }
    return demanderAllergenes();
  }

  case 'DONE': {
    return reponse('DONE', {
      text:
        `Ton profil existe déjà.\n` +
        `🏥 ${echapper(noms(maladies, brouillon.diseases))}\n` +
        `🚫 ${echapper(noms(allergenes, brouillon.allergens))}`,
    });
  }

  default:
    return demanderLangue();
}

// Récapitulatif écrit après les appels API : on reprend la charge utile
// calculée par la machine à états et on remplace le texte d'attente.
const charge = $('Machine à états').first().json;
const maladies = $('Référentiel maladies').all().map((i) => i.json);
const allergenes = $('Référentiel allergènes').all().map((i) => i.json);

const noms = (liste, ids) => {
  const trouves = liste.filter((x) => (ids || []).includes(x.id)).map((x) => x.name);
  return trouves.length ? trouves.join(', ') : 'aucune';
};
const echapper = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const d = charge.draft;
const texte =
  `✅ <b>Profil créé, ${echapper(d.first_name)} !</b>\n\n` +
  `🗣 Langue : ${d.language}\n` +
  `⚖️ Poids : ${d.weight ? d.weight + ' kg' : 'non renseigné'}\n` +
  `🏥 Maladies : ${echapper(noms(maladies, d.diseases))}\n` +
  `🚫 Allergies : ${echapper(noms(allergenes, d.allergens))}\n\n` +
  `Envoie-moi le nom d'un plat ou sa composition, et je te dis ce qu'il vaut pour toi.\n\n` +
  `<i>Ces informations ne remplacent pas l'avis d'un professionnel de santé.</i>`;

return [{
  json: {
    ...charge,
    telegram_body: { ...charge.telegram_body, text: texte, reply_markup: undefined },
  },
}];

// Point de convergence des deux branches : à partir d'ici, un seul objet,
// quel que soit le chemin emprunté.
return $input.all();
